import React, { useState, useEffect } from 'react';
import TaskForm from './components/TaskForm';
import TaskList from './components/TaskList';
import StatsChart from './components/StatsChart';
import Chatbot from './components/Chatbot';
import './App.css';

function App() {
  // Load tasks from localStorage on initial render
  const [tasks, setTasks] = useState(() => {
    const savedTasks = localStorage.getItem('prodtrack_tasks');
    return savedTasks ? JSON.parse(savedTasks) : [];
  });
  const [filter, setFilter] = useState('all');

  // Save tasks to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('prodtrack_tasks', JSON.stringify(tasks));
  }, [tasks]);

  const addTask = (taskData) => {
    const newTask = {
      id: Date.now(),
      text: taskData.text,
      priority: taskData.priority || 'Medium',
      category: taskData.category || 'General',
      completed: false,
      createdAt: new Date().toISOString(),
    };
    setTasks([...tasks, newTask]);
  };

  const toggleComplete = (id) => {
    setTasks(prevTasks =>
      prevTasks.map(task =>
        task.id === id ? { ...task, completed: !task.completed } : task
      )
    );
  };

  const deleteTask = (id) => {
    setTasks(prevTasks => prevTasks.filter(task => task.id !== id));
  };

  const getFilteredTasks = () => {
    let filtered = tasks;

    if (filter === 'active') {
      filtered = filtered.filter(task => !task.completed);
    } else if (filter === 'completed') {
      filtered = filtered.filter(task => task.completed);
    }

    // Sort by priority (High > Medium > Low)
    const priorityWeight = { High: 3, Medium: 2, Low: 1 };
    return [...filtered].sort((a, b) => priorityWeight[b.priority] - priorityWeight[a.priority]);
  };

  return (
    <div className="App">
      <header className="app-header">
        <div className="logo-container">
          <div className="app-logo">PT</div>
          <h1 className="app-title">ProdTrack</h1>
        </div>
        <div className="header-stats">
          <span className="stats-badge">
            {tasks.filter(t => t.completed).length}/{tasks.length} Done
          </span>
        </div>
      </header>

      <main className="app-main">
        <TaskForm addTask={addTask} />

        <div className="filter-buttons">
          <button className={`filter-btn ${filter === 'all' ? 'active' : ''}`} onClick={() => setFilter('all')}>All</button>
          <button className={`filter-btn ${filter === 'active' ? 'active' : ''}`} onClick={() => setFilter('active')}>Active</button>
          <button className={`filter-btn ${filter === 'completed' ? 'active' : ''}`} onClick={() => setFilter('completed')}>Completed</button>
        </div>

        <TaskList
          tasks={getFilteredTasks()}
          toggleComplete={toggleComplete}
          deleteTask={deleteTask}
        />

        <StatsChart tasks={tasks} />
      </main>

      <Chatbot />
    </div>
  );
}

export default App;
